package vn.codegym.inotes;import java.nio.file.*;import java.util.*;import java.util.stream.*;public class NoteFileStrategy implements NoteStrategy{private final Path file;public NoteFileStrategy(Path file){this.file=file;}private List<Note> read()throws Exception{if(!Files.exists(file))return new ArrayList<>();return Files.readAllLines(file).stream().filter(x->!x.isBlank()).map(x->{String[] p=x.split("\\|",4);return new Note(Integer.parseInt(p[0]),p[1],p[2],Integer.parseInt(p[3]));}).collect(Collectors.toCollection(ArrayList::new));}private void write(List<Note> list)throws Exception{Files.write(file,list.stream().map(n->n.id()+"|"+n.title()+"|"+n.content()+"|"+n.typeId()).toList());}public void save(Note n)throws Exception{List<Note> list=read();list.removeIf(x->x.id()==n.id());int id=n.id()==0?list.stream().mapToInt(Note::id).max().orElse(0)+1:n.id();list.add(new Note(id,n.title(),n.content(),n.typeId()));write(list);}public void delete(int id)throws Exception{List<Note> list=read();list.removeIf(n->n.id()==id);write(list);}public List<Note> findAll()throws Exception{return read();}public List<Note> search(String k)throws Exception{String q=k.toLowerCase();return read().stream().filter(n->n.title().toLowerCase().contains(q)||n.content().toLowerCase().contains(q)).toList();}}
